const ELEMENT_PROP_KEYS = new Set(["theme","before","after","hold","stagger","press","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  before: "Subtitles for every market in",
  after: ".",
  hold: 14,
  stagger: 3,
  press: 22,
  accent: "#E03C31",
  fontFamily: "Zen Kaku Gothic New",
  scale: 1,
  delay: 0,
  speed: 1,
};

type RubyPressElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof RubyPressBase>;

const RubyPressInner = forwardRef<
  HTMLDivElement,
  RubyPressElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<RubyPress>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <RubyPressBase
          {...(componentProps as unknown as ComponentProps<typeof RubyPressBase>)}
        />
      </div>
    </Sequence>
  );
});

export const RubyPress = Interactive.withSchema({
  Component: RubyPressInner,
  componentName: "<RubyPress>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
